PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sources(id TEXT PRIMARY KEY, kind TEXT NOT NULL, state TEXT NOT NULL, last_success TEXT, last_error TEXT, rights_status TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS securities(id TEXT PRIMARY KEY, ticker TEXT NOT NULL UNIQUE, cik TEXT NOT NULL, issuer_name TEXT NOT NULL, sector TEXT NOT NULL, data_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS universe_memberships(id TEXT PRIMARY KEY, security_id TEXT NOT NULL REFERENCES securities(id), universe TEXT NOT NULL, valid_from TEXT NOT NULL, valid_to TEXT, UNIQUE(security_id,universe,valid_from));
CREATE TABLE IF NOT EXISTS raw_documents(id TEXT PRIMARY KEY, source_id TEXT NOT NULL REFERENCES sources(id), external_id TEXT NOT NULL, sha256 TEXT NOT NULL, published_at TEXT NOT NULL, received_at TEXT NOT NULL, url TEXT NOT NULL, content BLOB NOT NULL, is_demo INTEGER NOT NULL DEFAULT 0, UNIQUE(source_id,external_id,sha256));
CREATE TABLE IF NOT EXISTS filings(id TEXT PRIMARY KEY, security_id TEXT NOT NULL REFERENCES securities(id), accession TEXT NOT NULL UNIQUE, form TEXT NOT NULL, accepted_at TEXT NOT NULL, raw_document_id TEXT NOT NULL REFERENCES raw_documents(id));
CREATE TABLE IF NOT EXISTS evidence_spans(id TEXT PRIMARY KEY, raw_document_id TEXT NOT NULL REFERENCES raw_documents(id), locator TEXT NOT NULL, excerpt TEXT NOT NULL, text_hash TEXT NOT NULL, level TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS facts(id TEXT PRIMARY KEY, security_id TEXT NOT NULL REFERENCES securities(id), evidence_id TEXT NOT NULL REFERENCES evidence_spans(id), metric_id TEXT NOT NULL, value_json TEXT NOT NULL, unit TEXT NOT NULL, period_start TEXT NOT NULL, period_end TEXT NOT NULL, fact_version INTEGER NOT NULL, supersedes TEXT REFERENCES facts(id));
CREATE TABLE IF NOT EXISTS events(id TEXT PRIMARY KEY, security_id TEXT NOT NULL REFERENCES securities(id), filing_id TEXT NOT NULL REFERENCES filings(id), family TEXT NOT NULL, event_type TEXT NOT NULL, event_at TEXT NOT NULL, parent_event_id TEXT REFERENCES events(id), snapshot_json TEXT NOT NULL, UNIQUE(filing_id,family,event_type));
CREATE TABLE IF NOT EXISTS market_snapshots(id TEXT PRIMARY KEY, captured_at TEXT NOT NULL, data_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS portfolio_snapshots(id TEXT PRIMARY KEY, captured_at TEXT NOT NULL, data_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS evaluations(id TEXT PRIMARY KEY, event_id TEXT NOT NULL REFERENCES events(id), evaluated_at TEXT NOT NULL, rule_version TEXT NOT NULL, input_json TEXT NOT NULL, core_json TEXT NOT NULL, core_hash TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS opportunities(id TEXT PRIMARY KEY, event_id TEXT NOT NULL UNIQUE REFERENCES events(id), state TEXT NOT NULL, evaluation_id TEXT NOT NULL REFERENCES evaluations(id), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS transitions(id INTEGER PRIMARY KEY AUTOINCREMENT, opportunity_id TEXT NOT NULL REFERENCES opportunities(id), from_state TEXT NOT NULL, to_state TEXT NOT NULL, reason_code TEXT NOT NULL, actor TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS order_intents(id TEXT PRIMARY KEY, opportunity_id TEXT NOT NULL REFERENCES opportunities(id), status TEXT NOT NULL, data_json TEXT NOT NULL, created_at TEXT NOT NULL, confirmed_at TEXT);
CREATE TABLE IF NOT EXISTS positions(id TEXT PRIMARY KEY, opportunity_id TEXT NOT NULL REFERENCES opportunities(id), quantity INTEGER NOT NULL, entry_price REAL NOT NULL, status TEXT NOT NULL, thesis_json TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS outcomes(id TEXT PRIMARY KEY, position_id TEXT NOT NULL REFERENCES positions(id), phase TEXT NOT NULL, data_json TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(position_id,phase));
CREATE TABLE IF NOT EXISTS exit_intents(id TEXT PRIMARY KEY, position_id TEXT NOT NULL REFERENCES positions(id), status TEXT NOT NULL, data_json TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS idempotency(key TEXT PRIMARY KEY, request_hash TEXT NOT NULL, response_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY AUTOINCREMENT, at TEXT NOT NULL, action TEXT NOT NULL, entity_id TEXT NOT NULL, details_json TEXT NOT NULL, previous_hash TEXT NOT NULL, hash TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS review_queue(id TEXT PRIMARY KEY, filing_id TEXT REFERENCES filings(id), status TEXT NOT NULL, reason TEXT NOT NULL, data_json TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS opportunities_state ON opportunities(state);
CREATE INDEX IF NOT EXISTS events_security ON events(security_id);
CREATE INDEX IF NOT EXISTS transitions_opportunity ON transitions(opportunity_id);
CREATE INDEX IF NOT EXISTS evaluations_event ON evaluations(event_id);
CREATE TABLE IF NOT EXISTS broker_tickets(id TEXT PRIMARY KEY, idempotency_key TEXT NOT NULL UNIQUE, request_hash TEXT NOT NULL, state TEXT NOT NULL, data_json TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS broker_receipts(id INTEGER PRIMARY KEY AUTOINCREMENT, ticket_id TEXT NOT NULL REFERENCES broker_tickets(id), kind TEXT NOT NULL, data_json TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS broker_executions(id TEXT PRIMARY KEY, ticket_id TEXT NOT NULL REFERENCES broker_tickets(id), data_json TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS integration_calculations(id TEXT PRIMARY KEY, kind TEXT NOT NULL, input_json TEXT NOT NULL, result_json TEXT NOT NULL, created_at TEXT NOT NULL);
